 $ai=$db->prepare("INSERT INTO qbook_customer_receipt_allocations(receipt_id,invoice_id,cash_amount,wht_amount,allocated_by)VALUES(?,?,?,?,?)");foreach($normalized as[$inv,$ca,$wa])$ai->execute([$id,$inv['id'],accounts_minor_decimal($ca),accounts_minor_decimal($wa),$user['id']]);if($wht>0)$db->prepare("INSERT INTO qbook_receipt_wht(receipt_id,tax_code_id,rate_snapshot,calculation_base_snapshot,accepted_amount,certificate_status,certificate_received_at)VALUES(?,?,?,?,?,?,?)")->execute([$id,$whtCode['id'],$whtCode['rate_percent'],$whtCode['calculation_base'],accounts_minor_decimal($wht),$cert,$cert==='CERTIFICATE_RECEIVED'?gmdate('Y-m-d H:i:s'):null]);$db->prepare("UPDATE qbook_customer_receipts SET status='POSTED',journal_id=?,posted_by=?,posted_at=UTC_TIMESTAMP() WHERE id=?")->execute([$j['id'],$user['id'],$id]);accounts_audit($db,$user,'CUSTOMER_RECEIPT_POSTED','CUSTOMER_RECEIPT',$id,['journal_id'=>$j['id'],'unapplied_cash'=>accounts_minor_decimal($cash-$cashAllocated),'unapplied_wht'=>accounts_minor_decimal($wht-$whtAllocated)]);return['receipt'=>['id'=>$id,'reference'=>billing_ref('RECEIPT',$r['reference_no']),'status'=>'POSTED'],'journal'=>$j];});});
